//! Cargo-driven `rshell.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", None),
        o => panic!("rshell-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:uuid", "engine:wine", "engine:c:cpprt", "engine:menuband_rust", "import:browseui", "import:uxtheme", "import:shlwapi", "import:advapi32", "import:shell32", "import:comctl32", "import:gdi32", "import:ole32", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:pseh", "engine:chkstk", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "body", "engine:oldnames", "import:kernel32_vista"],
        "x86_64" => &["engine:uuid", "engine:wine", "engine:c:cpprt", "engine:menuband_rust", "import:browseui", "import:uxtheme", "import:shlwapi", "import:advapi32", "import:shell32", "import:comctl32", "import:gdi32", "import:ole32", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:pseh", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "body", "engine:oldnames", "import:kernel32_vista"],
        "aarch64" => &["engine:uuid", "engine:wine", "engine:c:cpprt", "engine:menuband_rust", "import:browseui", "import:uxtheme", "import:shlwapi", "import:advapi32", "import:shell32", "import:comctl32", "import:gdi32", "import:ole32", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:pseh", "engine:chkstk", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "body", "engine:oldnames", "import:kernel32_vista"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("rshell_shims", &["base/shell/rshell/CQuickLaunchBand.cpp", "base/shell/rshell/misc.cpp"])
        .whole_c_objects("rshell_shims")
        .c_from_compile_db("shellbars", &["dll/win32/browseui/shellbars/CBandSite.cpp", "dll/win32/browseui/shellbars/CBandSiteMenu.cpp", "dll/win32/browseui/shellbars/CBaseBar.cpp", "dll/win32/browseui/shellbars/CISFBand.cpp", "dll/win32/browseui/shellbars/CSHEnumClassesOfCategories.cpp"])
        .whole_c_objects("shellbars")
        .spec2def("base/shell/rshell/rshell.spec", "rshell.dll")
        .import_lib("dll/win32/browseui/browseui.spec", "browseui.dll", "browseui")
        .import_lib("dll/win32/uxtheme/uxtheme.spec", "uxtheme.dll", "uxtheme")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
